import numpy as np
# centers in demo2 patterns sorted names
p={'2':(2,11),'6':(2,23),'8':(9,3),'0':(17,10),'9':(24,3),'5':(25,10)}
# sort by coordinates under 8 D4 transforms, row then col
trans={
'id':lambda r,c:(r,c),'rot90':lambda r,c:(c,-r),'rot180':lambda r,c:(-r,-c),'rot270':lambda r,c:(-c,r),
'flipH':lambda r,c:(r,-c),'flipV':lambda r,c:(-r,c),'diag':lambda r,c:(c,r),'anti':lambda r,c:(-c,-r)}
for k,f in trans.items():
 print(k, ''.join(sorted(p,key=lambda n:f(*p[n]))))
